let correctionId=null;
import * as C from './core.mjs';
import {installOffline} from './offline.mjs';
import {openStore,loadStore,saveStore,snapshots,storageHealth,saveDraft,loadDrafts,removeDraft,syncRecovery} from './storage.mjs';
const root=document.querySelector('#app');
let pendingForm=null,failedDraft=null,drafts=[],activeDraftId=null,purchasePreview=null,purchasePreviewInput=null,activityFilters={account:"",category:"",from:"",to:"",status:"all"},activityPage=0,offlineStatus='Preparing offline shell…',goalPathPreview=null,goalPathInput=null,debtComparison=null,debtInput=null,singlePayoff=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=C.fresh(),db,revision=0,tab='home',busy=false,error='',saved='Opening storage…',preview=null,csv=null,csvRows=null,query='',filter='all',budgetKey='',scenario={mode:'budget',extraExpense:0,incomeChange:0},restores=[];
const cash=n=>n===null?'Balance check needed':new Intl.NumberFormat('en',{style:'currency',currency:state.currency,maximumFractionDigits:2}).format(n/100);
const now=()=>C.today(state.timezone);
const period=()=>C.workspacePeriod(state,now());
const accountName=id=>state.accounts.find(a=>a.id===id)?.name||id;
const categoryName=id=>state.categories.find(c=>c.id===id)?.name||'Uncategorized';
const activeGoals=()=>state.goals.filter(g=>!g.archived);
function notify(text){document.querySelector('#notification').textContent=text;setTimeout(()=>{document.querySelector('#notification').textContent='';},5000);}
function button(text,action,cls='',data=''){return `<button class="button ${cls}" data-action="${esc(action)}" ${data} ${busy?'disabled':''}>${esc(text)}</button>`;}
function field(label,name,type='text',value='',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,value=''){return `<label>${esc(label)}<select name="${esc(name)}">${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;}
function accountsOptions(kind){return state.accounts.filter(a=>!kind||a.kind===kind).map(a=>[a.id,a.name]);}
function header(title,description){return `<div class="topbar"><div><div class="eyebrow">Your money, with a direction</div><h1>${esc(title)}</h1><p class="subtitle">${esc(description)}</p></div><div class="status ${error?'error':''}">${esc(saved)}</div></div>`;}
function render(){
  if(!db&&saved==='Opening storage…'){root.innerHTML='<div class="intro"><div class="brand">PLAN</div><p>Opening your private workspace…</p></div>';return;}
  const nav=[['home','Overview'],['plan','Planner'],['log','Activity'],['goals','Goals'],['more','More']];
  root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">P<span>L</span>AN</div><nav aria-label="Main navigation">${nav.map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="sidefoot">Private on this device<br><span class="muted">Cloud sync not connected</span><br><span id="offline-status">${esc(offlineStatus)}</span></div></aside><main id="content" tabindex="-1">${error?`<div class="errorbanner" role="alert">${esc(error)}<div class="actions">${button('Download recovery copy','export','quiet')}${button('Dismiss','dismiss','quiet')}</div></div>`:''}${({home:home,plan:planner,log:activity,goals:goals,more:more,accounts:accounts,budget:budget,notes:notes,reports:reports,backup:backup,calendar:calendar,outside:outside,settings:settings,ai:assistant,debts:debts}[tab]||home)()}</main></div>`;
  bind();
  if(drafts.length){const banner=document.createElement('section');banner.className='notice';banner.innerHTML=`<strong>${drafts.length} unsaved draft(s) retained</strong><p>These changes were not applied. Download them for review before entering them against your latest records.</p>${drafts.map(d=>`<div class="actions">${button(`Download draft · ${d.form?.id||'change'}`,'export-draft','quiet',`data-id="${esc(d.id)}"`)}${d.form?button('Review entry draft','review-draft','quiet',`data-id="${esc(d.id)}"`):''}${button('Discard draft','discard-draft','quiet',`data-id="${esc(d.id)}"`)}</div>`).join('')}`;root.querySelector('main').prepend(banner);banner.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(()=>action(b.dataset.action,b.dataset)));}
  if(failedDraft?.form&&failedDraft.tab===tab){const f=[...root.querySelectorAll('form')].find(f=>(f.id||f.dataset.form)===failedDraft.form.id&&(f.dataset.id||'')===(failedDraft.form.record||''));if(f)for(const [name,value]of Object.entries(failedDraft.form.values)){const input=f.elements.namedItem(name);if(input&&input.type!=='file'){if(input.type==='checkbox')input.checked=!!value;else input.value=value;}}}
}
function insightsCard(){const items=C.spendingInsights(state);return `<section class="card"><h2>What your records show</h2><ul class="list">${items.map(i=>`<li><strong>${esc(i.title)}</strong><p>${i.kind==='over-budget'?`${esc(cash(i.amount))} above the period budget.`:i.kind==='review'?`${i.count} recorded entries need a category before patterns can be learned.`:i.kind==='balance-review'?`${i.count} unresolved balance check(s).`:'Missing records do not mean there was no spending.'}</p><small>${i.evidence.length} supporting record(s)</small></li>`).join('')||'<li>No budget overruns in the recorded categories. Tracking may still be incomplete.</li>'}</ul><div class="actions">${button('Review activity','navigate','quiet','data-to="log"')}</div></section>`;}
function weeklyCard(){const review=C.weeklyReview(state);return `<section class="card"><h2>Your weekly review</h2><ul class="list">${review.items.map(i=>`<li><strong>${esc(i.title)} · ${i.count}</strong><p>${esc(i.detail)}</p>${button('Review','navigate','quiet',`data-to="${i.target}"`)}</li>`).join('')||'<li>The automatic checks found no pending review items. Still compare your statements and check for missing entries.</li>'}</ul><p class="subtitle">${esc(review.coverage)}</p></section>`;}
function home(){
  if(!state.accounts.length)return `${header('Welcome to PLAN.','Bring your records with you, then give every goal a clear path.')}<section class="hero"><div class="eyebrow">A fresh foundation</div><h2>Your history belongs here.</h2><p class="subtitle">Import your existing PLAN backup. Monthly budgets stay as plans; actual records stay as records. Your original file is kept intact inside the new backup.</p><div class="actions">${button('Import PLAN backup','navigate','primary','data-to="backup"')}${button('Start empty','start','quiet')}</div></section><div class="grid"><div class="card"><h2>One pool of money</h2><p>Plan several purchases together without promising the same savings twice.</p></div><div class="card"><h2>A small weekly habit</h2><p>Quick entries, imports and a weekly balance check keep your plan useful.</p></div></div>`;
  const sum=C.summary(state),next=C.periodForecast(state,C.addMonths(period(),1)),dates=C.workspacePeriodDates(state,period()),unresolved=state.reconciliations.filter(r=>r.status==='unresolved');
  const legacyEstimate=state.legacy?.estimates.filter(e=>e.key<period()).reduce((n,e)=>n+(e.recorded??e.predicted),0);
  return `${header(state.name?`Your next move, ${state.name}.`:'Your money, in view.',`${dates.from} – ${dates.to} · Your financial period`)}
  ${dates.transition?`<div class="notice">This is a cycle transition period. Review its salary and spending budget for ${esc(dates.from)} to ${esc(dates.to)}; its length differs from a normal month.</div>`:''}
  ${sum.missing?`<div class="notice"><strong>First, check the balances you actually have.</strong><p>${legacyEstimate!=null?`Your legacy history estimates ${esc(cash(legacyEstimate))} saved. That estimate is preserved, but it is not a verified account balance.`:'Enter your bank and wallet balances to begin.'} Future salaries and money owed to you stay outside available cash.</p>${button('Check balances','navigate','primary','data-to="accounts"')}</div>`:''}
  <section class="hero"><div class="row"><div><div class="eyebrow">Unreserved cash, today</div><div class="big ${sum.available!==null&&sum.available<0?'negative':''}">${esc(cash(sum.available))}</div></div><span class="tag">${sum.missing?'Awaiting verification':'From your balance checks'}</span></div><p>${sum.available!==null&&sum.available<0?(sum.cash<0?'Your liquid balance is negative. Review transactions and upcoming income; keep the shortfall visible.':'Your reservations exceed your cash. Review balances and release or reduce reservations.'):'After goal reservations and your protected reserve. Upcoming bills still need their own cash-flow check.'}</p><div class="actions">${button('Plan a purchase','navigate','primary','data-to="goals"')}${button('Record spending','navigate','quiet','data-to="log"')}</div></section>
  <div class="stats"><div class="card"><small>Liquid cash</small><div class="number">${esc(cash(sum.cash))}</div><small>${sum.missing?'Incomplete balances':'Bank + wallet'}</small></div><div class="card"><small>Reserved for goals</small><div class="number">${esc(cash(sum.reserved))}</div><small>Still part of your cash</small></div><div class="card"><small>Outstanding debt</small><div class="number">${esc(cash(sum.debt))}</div><small>${sum.debtMissing?'Incomplete debt balances':sum.debtVerified?'Separate from spending':'Unverified debt estimate'}</small></div></div>
  <div class="grid split"><section class="card"><div class="row"><h2>Next period’s capacity</h2><span class="tag">Budget assumption</span></div><div class="number ${next.capacity<0?'negative':'positive'}">${esc(cash(next.capacity))}</div><p>${esc(cash(next.income))} expected income − ${esc(cash(next.spending))} spending budget − ${esc(cash(next.buffer))} buffer${next.committed?` − ${esc(cash(next.committed))} ongoing purchase costs`:''}.</p><p>Amounts may change when actual income and spending are recorded.</p><div class="actions">${button('Explore the schedule','navigate','quiet','data-to="plan"')}${button('Review budgets','navigate','quiet','data-to="budget"')}</div></section><section class="card"><h2>Your next useful actions</h2><ul class="list"><li>${sum.missing?'Confirm account balances':'Review this week’s transactions'}</li><li>${unresolved.length?`${unresolved.length} balance difference(s) need investigation`:'Keep your next bills on the cash calendar'}</li><li>${activeGoals().filter(g=>!g.protected).length?'Review competing goal dates':'Add a purchase and choose its priority'}</li></ul><div class="actions">${button('Weekly check','navigate','quiet','data-to="accounts"')}${button('Cash calendar','navigate','quiet','data-to="calendar"')}</div></section></div><div class="grid">${weeklyCard()}${insightsCard()}</div>`;
}
function planner(){
  const result=C.planGoals(state,scenario),active=result.results,protection=scenario.protection??state.settings.monthlyProtection;
  return `${header('Give your goals a path.','Compare choices before committing your money. Each goal draws from the same pool.')}
  <div class="grid split"><section class="card"><h2>Try a scenario</h2><form id="scenario"><div class="formgrid">${select('Forecast baseline','mode',[['budget','My budget'],['history','Budget + recorded history'],['conservative','Conservative: spending +15%']],scenario.mode)}${field('Extra cost each period','extraExpense','number',scenario.extraExpense/100,'min="0" step="0.01"')}${field('Income change each period','incomeChange','number',scenario.incomeChange/100,'step="0.01"')}${field('Continue adding to protected savings','protection','number',protection/100,'min="0" step="0.01"')}</div><button class="button primary">Compare schedule</button></form><p class="subtitle">Scenario changes do not alter your budgets. The protected-savings contribution is a planning preference you can save below.</p>${button('Save reserve contribution','save-protection','quiet')}</section><section class="card"><h2>Why these dates?</h2><ul class="list">${result.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></section></div>
  ${result.warnings.map(w=>`<div class="notice">${esc(w.replace(/(\d+) minor units/g,(_,n)=>cash(Number(n))))}</div>`).join('')}
  <section class="card wide"><h2>Your goals, together</h2>${!active.length?`<div class="empty"><h2>Add a purchase to start</h2><p>Protected saving goals are kept out of the purchase pool.</p>${button('Add a goal','navigate','primary','data-to="goals"')}</div>`:`<div class="tablewrap"><table><thead><tr><th>Goal / priority</th><th>Target</th><th>Reserved now</th><th>Forecast funding date</th><th>Desired date</th></tr></thead><tbody>${active.map(g=>`<tr><td>${esc(g.name)}<br><small>Priority ${state.goals.find(x=>x.id===g.id).priority}</small></td><td class="money">${esc(cash(g.target))}</td><td class="money">${esc(cash(state.reservations[g.id]||0))}</td><td>${g.ready?esc(g.ready):'Not achievable in this horizon'}<br><span class="tag ${g.late?'negative':''}">${g.late?'Desired date missed':'Forecast'}</span></td><td>${esc(g.deadline||'Flexible')}</td></tr>`).join('')}</tbody></table></div>`}</section>
  <div class="grid"><section class="card wide"><h2>Period-by-period funding</h2><div class="tablewrap"><table><thead><tr><th>Period ending</th><th>Surplus</th><th>Protected contribution</th><th>Goal funding</th><th>Pool remaining</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${esc(r.date)}</td><td class="money ${r.capacity<0?'negative':''}">${esc(cash(r.capacity))}</td><td class="money">${esc(cash(r.protected))}</td><td class="money">${esc(cash(r.allocated||0))}</td><td class="money">${esc(cash(r.pool))}${r.shortage?'<br><span class="negative">Shortfall</span>':''}</td></tr>`).join('')}</tbody></table></div></section></div>`;
}
function correctionCard(){const t=state.transactions.find(t=>t.id===correctionId);if(!t||!C.canCorrectTransaction(state,t.id))return '';return `<section class="card"><h2>Review a replacement entry</h2><p>Original: ${esc(t.date)} · ${esc(cash(t.amount))} · ${esc(accountName(t.account))} · ${esc(t.note||'No description')}. It remains in history with a linked reversal.</p><form id="correction" data-id="${esc(t.id)}"><div class="formgrid">${select('Corrected type','kind',[['expense','Spending'],['income','Income'],['refund','Refund']],t.kind)}${field('Corrected amount','amount','number',t.amount/100,'min="0.01" step="0.01" required')}${field('Corrected date','date','date',t.date,'required')}${select('Corrected account','account',accountsOptions(),t.account)}${select('Corrected category','category',state.categories.filter(c=>!['savings','buffer'].includes(c.type)).map(c=>[c.id,c.name]),t.category)}${field('Corrected description','note','text',t.note,'maxlength="10000"')}${field('Why this correction?','reason','text','','required maxlength="10000"')}</div>${t.splits?'<p>This entry has split categories. Use reversal and a new split entry to retain the intended allocation.</p>':'<p>Compare the original with the replacement above. Entries already included in a later balance check change history; recheck your balance if needed.</p>'}<button class="button primary" ${t.splits?'disabled':''}>Save reviewed correction</button></form>${button('Cancel correction','cancel-correction','quiet')}</section>`;}
function activity(){
  const reversed=new Set(state.transactions.filter(t=>t.reverses).map(t=>t.reverses));
  const tx=state.transactions.filter(t=>(filter==='all'||(filter==='legacy'?t.historical:t.kind===filter))
    &&(!activityFilters.account||t.account===activityFilters.account||t.toAccount===activityFilters.account)
    &&(!activityFilters.category||t.category===activityFilters.category||t.splits?.some(p=>p.category===activityFilters.category))
    &&(!activityFilters.from||t.date>=activityFilters.from)&&(!activityFilters.to||t.date<=activityFilters.to)
    &&(activityFilters.status==='all'||activityFilters.status==='active'&&!reversed.has(t.id)&&t.kind!=='reversal'||activityFilters.status==='reversed'&&reversed.has(t.id)||activityFilters.status==='corrections'&&t.kind==='reversal')
    &&`${t.note||''} ${categoryName(t.category)} ${(t.splits||[]).map(p=>categoryName(p.category)).join(' ')} ${accountName(t.account)} ${accountName(t.toAccount)}`.toLowerCase().includes(query.toLowerCase())).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.seq-a.seq);
  const pages=Math.max(1,Math.ceil(tx.length/100));activityPage=Math.min(activityPage,pages-1);const visibleTx=tx.slice(activityPage*100,(activityPage+1)*100);
  return `${header('Keep reality in the picture.','Record what happened—even if it went beyond your budget.')}
  <div class="grid split"><section class="card"><h2>Quick entry</h2><form id="transaction"><div class="formgrid">${select('What happened?','kind',[['expense','Spending'],['income','Income'],['refund','Refund'],['transfer','Transfer between my accounts'],['repayment','Debt / card payment'],['borrow','Borrowed money'],['loan-out','Money given / lent'],['loan-return','Money returned']])}${field('Amount','amount','number','','min="0.01" step="0.01" required')}${field('Date','date','date',now(),'required')}${select('From / affected account','account',accountsOptions())}${select('Destination (transfer, borrowing or repayment)','toAccount',[['','Not applicable'],...accountsOptions()])}${select('Category','category',state.categories.filter(c=>!c.archived&&!['savings','buffer'].includes(c.type)).map(c=>[c.id,c.name]),'oneoff')}${field('Description','note','text','','maxlength="10000"')}</div><details><summary>Split across two categories</summary><div class="formgrid">${select('First category','splitCategory1',state.categories.filter(c=>!c.archived&&!['savings','buffer'].includes(c.type)).map(c=>[c.id,c.name]))}${field('First amount','splitAmount1','number','','min="0.01" step="0.01"')}${select('Second category','splitCategory2',state.categories.filter(c=>!c.archived&&!['savings','buffer'].includes(c.type)).map(c=>[c.id,c.name]))}${field('Second amount','splitAmount2','number','','min="0.01" step="0.01"')}</div><p>The two amounts must equal the total above. Spending and refunds support splits.</p></details><button class="button primary">Save entry</button></form><p class="subtitle">Card payments reduce cash and debt. They do not count the original purchase as spending again. Entries dated before your latest balance check update history without changing that checked balance. For entries on the same day, confirm the balance again if it already included them.</p></section><section class="card"><h2>Import transactions</h2><p>Use a CSV from your bank or a simple export. Map columns, preview every row, then import. Duplicate rows are skipped.</p><div class="actions">${button('CSV import','navigate','quiet','data-to="backup"')}</div><hr class="divider"><h3>Correct a mistake</h3><p>Choose Correct to review a replacement for ordinary spending, income or refunds, or Reverse to undo an entry. The original stays in history.</p></section></div>
  ${correctionCard()}<section class="card"><div class="row"><h2>All activity</h2><span class="tag">${state.transactions.length} records</span></div><form id="search" class="no-print"><div class="formgrid">${field('Search notes, accounts or categories','query','search',query)}${select('Show','filter',[['all','All records'],['expense','Spending'],['income','Income'],['refund','Refunds'],['repayment','Debt payments'],['transfer','Transfers'],['borrow','Borrowing'],['loan-out','Money sent'],['loan-return','Money returned'],['reversal','Corrections'],['legacy','Imported history']],filter)}${select('Account filter','account',[['','All accounts'],...accountsOptions()],activityFilters.account)}${select('Category filter','category',[['','All categories'],...state.categories.map(c=>[c.id,c.name])],activityFilters.category)}${field('From date','from','date',activityFilters.from)}${field('Through date','to','date',activityFilters.to)}${select('Correction status','status',[['all','All statuses'],['active','Uncorrected entries'],['reversed','Reversed originals'],['corrections','Correction entries']],activityFilters.status)}</div><button class="button quiet">Filter</button></form><div class="tablewrap"><table><thead><tr><th>Date / note</th><th>Category / type</th><th>Amount</th><th>Account</th><th>Status</th></tr></thead><tbody>${visibleTx.map(t=>`<tr><td>${esc(t.date)}<br>${esc(t.note||'No description')}</td><td>${t.splits?t.splits.map(p=>`${esc(categoryName(p.category))} ${esc(cash(p.amount))}`).join("<br>"):esc(categoryName(t.category))}<br><small>${esc(t.kind)}</small></td><td class="money">${esc(cash(t.amount))}${t.corrects?'<br><small>Reviewed replacement</small>':''}</td><td>${esc(accountName(t.account))}${t.toAccount?` → ${esc(accountName(t.toAccount))}`:''}</td><td>${t.historical?'<span class="tag">Historical · not reposted</span>':reversed.has(t.id)?'<span class="tag">Reversed</span>':t.kind==='reversal'?'<span class="tag">Correction</span>':button('Reverse','reverse','quiet',`data-id="${esc(t.id)}"`)+(C.canCorrectTransaction(state,t.id)&&!t.splits?button('Correct','correct-entry','quiet',`data-id="${esc(t.id)}"`):'')}</td></tr>`).join('')||'<tr><td colspan="5">No matching transactions.</td></tr>'}</tbody></table></div><p>${tx.length} matching · page ${activityPage+1} of ${pages} · up to 100 entries per page</p><div class="actions">${activityPage?button('Previous entries','activity-page','quiet',`data-page="${activityPage-1}"`):''}${activityPage<pages-1?button('Next entries','activity-page','quiet',`data-page="${activityPage+1}"`):''}${button('Clear filters','clear-filters','quiet')}</div></section>`;
}
function goals(){
  const forecast=C.planGoals(state,scenario);
  return `${header('Make room for what matters.','Reserve real money now, or plan how to fund a purchase over time.')}
  <div class="grid goals-grid">${activeGoals().map(g=>{
    const reserved=state.reservations[g.id]||0,purchased=C.goalPurchases(g).reduce((total,p)=>total+p.amount,0),r=forecast.results.find(r=>r.id===g.id);
    return `<section class="card goal"><div class="row goaltop"><div><span class="eyebrow">${g.protected?'Protected savings':`Priority ${g.priority}`}</span><div class="goalname">${esc(g.icon||'◇')} ${esc(g.name)}</div></div><span class="tag">${esc(g.kind||'saving')}</span></div><div><span class="number">${esc(cash(reserved))}</span><small> / ${esc(cash(g.target))}</small></div>${purchased?`<p>Already purchased ${esc(cash(purchased))} · still to buy ${esc(cash(C.goalRemaining(g)))}</p>`:''}<progress value="${Math.min(reserved+purchased,g.target)}" max="${Math.max(1,g.target)}" aria-label="${esc(g.name)} funding"></progress><p>${g.protected?'This money is excluded from purchase planning.':r?.ready?`Forecast funding: ${esc(r.ready)}`:'Add income capacity or adjust the target to find a date.'}</p><small>${g.desired?`Desired: ${esc(g.desired)}`:'Flexible date'} · ${g.recurringCost?`Ongoing cost: ${esc(cash(g.recurringCost))} / period`:''}</small><details><summary>Manage this goal</summary><form data-form="reserve" data-id="${esc(g.id)}">${field('Amount to reserve / release','amount','number','','min="0.01" step="0.01" required')}${select('Action','action',[['reserve','Reserve from available cash'],['release','Release to available cash']])}<button class="button">Apply reservation</button></form><form data-form="goal-edit" data-id="${esc(g.id)}"><div class="formgrid">${field('Target','target','number',g.target/100,'min="0" step="0.01" required')}${field('Priority','priority','number',g.priority,'min="1" max="100" required')}${field('Desired date','desired','date',g.desired)}${select('Date flexibility','flexibility',[['flexible','Flexible desired date'],['hard','Must be funded by this date']],g.flexible===false?'hard':'flexible')}</div><button class="button">Save goal changes</button></form>${g.kind!=='saving'?`<form data-form="purchase" data-id="${esc(g.id)}">${field('Actual purchase cost','amount','number',C.goalRemaining(g)/100,'min="0.01" step="0.01" required')}${select('Pay from','account',accountsOptions('asset'))}${field('Purchase date','date','date',now(),'required')}${select('Purchase progress','completion',[['complete','This finishes the goal'],['partial','Partial purchase / installment']])}${g.kind==='gold'?field('Actual quantity bought','quantity','number','','min="0.001" step="0.001"'):''}<button class="button primary">Record purchase</button></form>`:''}${button('Archive and release funds','archive-goal','danger',`data-id="${esc(g.id)}"`)}</details></section>`;
  }).join('')}</div>
  <div class="grid"><section class="card"><h2>Add a goal or purchase</h2><form id="goal"><div class="formgrid">${field('Name','name','text','','required maxlength="300"')}${field('Target price / amount','target','number','','min="0.01" step="0.01" required')}${select('Kind','kind',[['purchase','Purchase'],['saving','Savings'],['gold','Gold purchase']])}${field('Priority (1 first)','priority','number',activeGoals().length+1,'min="1" max="100" required')}${field('Desired date (optional)','desired','date')}${select('Date flexibility','flexibility',[['flexible','Flexible desired date'],['hard','Must be funded by this date']])}${field('Ongoing cost each period','recurringCost','number','0','min="0" step="0.01"')}<label class="check full"><input name="protected" type="checkbox">Protect this goal’s money from purchases</label></div><details><summary>Gold / quantity details</summary><div class="formgrid">${field('Quantity target (e.g. grams)','quantity','number','','min="0" step="0.001"')}${field('Price quote per unit','unitPrice','number','','min="0" step="0.01"')}${field('Fees included in the target','fees','number','0','min="0" step="0.01"')}${field('Quote date','quoteDate','date',now())}</div><p>Target amount is the total budget, including fees. Prices are manual, dated quotes; future appreciation is never required for affordability.</p></details><button class="button primary">Add goal</button></form></section><section class="card"><h2>Completed and archived</h2><ul class="list">${state.goals.filter(g=>g.archived).map(g=>`<li>${esc(g.name)} <span class="tag">${g.completed?'Purchased':'Archived'}</span><br><small>History retained; unused reservation released.</small></li>`).join('')||'<li>No archived goals yet.</li>'}</ul><hr class="divider"><h2>Gold holdings</h2><ul class="list">${state.holdings.filter(h=>!h.reversedBy).map(h=>`<li>${esc(h.name)} · ${esc(h.quantity||'Unspecified quantity')}<br><small>Cost ${esc(cash(h.cost))} · ${esc(h.date)}</small></li>`).join('')||'<li>Record a gold purchase to keep its cost and quantity here.</li>'}</ul></section></div>`;
}
function accounts(){
  return `${header('A weekly check, a clearer picture.','Enter the balances you see in your bank or wallet. Debt balances use a minus sign.')}
  <div class="grid">${state.accounts.map(a=>{const balance=C.accountBalance(state,a.id),last=state.reconciliations.filter(r=>r.account===a.id).at(-1);return `<section class="card"><div class="row"><h2>${esc(a.name)}</h2><span class="tag">${a.kind==='asset'?'Cash account':'Liability'}</span></div><div class="number ${balance!==null&&balance<0?'negative':''}">${esc(cash(balance))}</div><p>${a.opening===null?'No opening balance recorded':a.verified?`Last checked ${esc(a.baselineDate)}`:'Opening balance · verify against your statement'}</p>${a.limit?`<p>Credit limit ${esc(cash(a.limit))} · available ${esc(cash(Math.max(0,Math.min(a.limit,a.limit+(balance||0)))))}</p>`:''}<form data-form="reconcile" data-id="${esc(a.id)}"><div class="formgrid">${field('Balance now','balance','number',balance===null?'':balance/100,'step="0.01" required')}${field('Balance date','date','date',now(),'required min="'+esc(a.baselineDate)+'"')}${field('Explanation (optional)','note','text')}</div><button class="button primary">Confirm balance</button></form>${last?.status==='unresolved'?`<div class="notice">Difference ${esc(cash(last.difference))}. It remains unresolved; it has not been assigned to a spending category.</div>`:''}</section>`;}).join('')}
  <section class="card"><h2>Add an account</h2><form id="account">${field('Account name','name','text','','required maxlength="300"')}${select('Type','kind',[['asset','Bank / cash / savings'],['liability','Debt / credit']])}<button class="button">Add account</button></form></section></div><section class="card"><h2>Balance-check history</h2><div class="tablewrap"><table><thead><tr><th>Date</th><th>Account</th><th>Balance</th><th>Difference</th><th>Status</th></tr></thead><tbody>${state.reconciliations.slice().reverse().map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(accountName(r.account))}</td><td>${esc(cash(r.balance))}</td><td>${r.difference===null?'First baseline':esc(cash(r.difference))}</td><td>${esc(r.status)}<br><small>${esc(r.note)}</small>${r.review?`<p>${esc(r.review.note)}</p>`:''}${r.status==='unresolved'?`<form data-form="balance-review" data-id="${esc(r.id)}">${field('Why the difference is understood','note','text','','required maxlength="10000"')}<button class="button">Mark difference reviewed</button></form>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No balance checks yet.</td></tr>'}</tbody></table></div></section>`;
}
function budget(){
  budgetKey=budgetKey||C.addMonths(period(),1);
  const b=state.budgets.find(b=>b.key===budgetKey)||C.periodForecast(state,budgetKey).budget;
  const historical=budgetKey<period();
  const total=b?Object.values(b.alloc).reduce((a,b)=>a+b,0):0;
  return `${header('Plan what each period needs.','Budgets are intentions. They do not create transactions or confirm savings.')}
  <section class="card"><form id="budget-period">${field('Financial month (starts on your cycle day)','key','month',budgetKey,'required')}<button class="button">View period</button></form></section>
  <div class="grid"><section class="card"><h2>${esc(budgetKey)} budget ${historical?'· Historical':''}</h2>${historical?'<div class="notice">This historical plan stays intact. Corrections to actual money belong in the transaction ledger.</div>':''}<form id="budget" data-key="${esc(budgetKey)}">${field('Expected salary','salary','number',(b?.salary||0)/100,`min="0" step="0.01" required ${historical?'disabled':''}`)}<div class="formgrid">${state.categories.filter(c=>!c.archived&&c.id!=='oneoff').map(c=>field(c.name,`alloc:${c.id}`,'number',(b?.alloc[c.id]||0)/100,`min="0" step="0.01" ${historical?'disabled':''}`)).join('')}</div><button class="button primary" ${historical?'disabled':''}>Save budget</button></form></section><section class="card"><h2>Budget feasibility</h2><div class="number ${b&&total>b.salary?'negative':''}">${esc(cash((b?.salary||0)-total))}</div><p>${b&&total>b.salary?'Your allocations exceed expected income. The shortfall is visible; PLAN will not quietly move locked money.':'Unallocated income after all budget categories, including savings and buffer.'}</p><hr class="divider"><h3>Keep spending categories useful</h3><ul class="list">${state.categories.filter(c=>!['oneoff','savings','buffer'].includes(c.id)).map(c=>`<li>${esc(c.name)} ${c.archived?'<span class="tag">Archived</span>':''}${button(c.archived?'Restore category':'Archive category','category-archive','quiet',`data-id="${esc(c.id)}"`)}</li>`).join('')}</ul><form id="category">${field('Category name','name','text','','required maxlength="300"')}${select('Type','type',[['variable','Flexible spending'],['fixed','Fixed bill']])}<button class="button">Add category</button></form><p class="subtitle">Category types are retained in imported historical plans. Dates and budget revisions stay in the audit history.</p></section></div>`;
}
function calendar(){
  const result=C.cashCalendar(state),end=new Date(`${now()}T12:00:00Z`);end.setUTCDate(end.getUTCDate()+60);const events=C.scheduledEvents(state,{from:now(),to:end.toISOString().slice(0,10),includeOverdue:true});
  return `${header('See the gaps between paydays.','Put income and bills on their actual dates before making a purchase.')}
  ${result.warnings.map(w=>`<div class="notice">${esc(w)}</div>`).join('')}
  <section class="card"><h2>Would a purchase leave enough for normal life?</h2><form id="purchase-preview"><div class="formgrid">${field('Proposed cost','amount','number',purchasePreviewInput?.amount||'','min="0.01" step="0.01" required')}${field('Proposed purchase date','date','date',purchasePreviewInput?.date||now(),'required')}${select('Purchase account','account',accountsOptions('asset'),purchasePreviewInput?.account||'')}${select('Normal spending account','budgetAccount',accountsOptions('asset'),purchasePreviewInput?.budgetAccount||'')}${field('Days to check','days','number',purchasePreviewInput?.days||60,'min="1" max="365" required')}${select('Goal reservation to use','goalId',[['','New purchase · keep all reservations'],...state.goals.filter(g=>!g.archived&&!g.protected&&g.kind!=='saving').map(g=>[g.id,g.name])],purchasePreviewInput?.goalId||'')}${select('Timing check','mode',[['date','Check my proposed date'],['earliest','Find earliest conditional date']],purchasePreviewInput?.mode||'date')}</div><button class="button primary">Check purchase timing</button></form>${purchasePreview?`<div class="notice"><strong>${!purchasePreview.known?'Check account balances first':purchasePreview.missingBudget?'Add a spending budget before relying on this preview':purchasePreview.safe?(purchasePreview.conditional?'Fits if the scheduled income arrives':'Fits the entered spending assumptions'):'This purchase leaves a cash or reservation shortfall'}</strong><p>${purchasePreview.dateSearch?`Earliest conditional purchase: ${purchasePreview.earliest?esc(purchasePreview.earliest):'No date fits within this checked horizon'}. `:''}Lowest projected cash: ${esc(cash(purchasePreview.minimum))}. Reserved floor: ${esc(cash(purchasePreview.floor))}. Checked through ${esc(purchasePreview.through)}.</p><ul class="list">${purchasePreview.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}${purchasePreview.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div>`:''}</section>
  <div class="grid"><section class="card"><h2>Next 60 days</h2><div class="number ${result.minimum!==null&&result.minimum<0?'negative':''}">${esc(cash(result.minimum))}</div><p>Lowest projected liquid cash on the entered schedule. Daily food and other unscheduled spending are not included yet.</p><div class="tablewrap"><table><thead><tr><th>Date</th><th>Event</th><th>Amount</th><th>Cash after</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.name)}</td><td>${esc(cash(r.amount))}</td><td class="${r.balance<0?'negative':''}">${esc(cash(r.balance))}</td></tr>`).join('')||'<tr><td colspan="4">Add dated events to see daily liquidity.</td></tr>'}</tbody></table></div></section>
  <section class="card"><h2>Schedule an event</h2><form id="obligation">${field('Name','name','text','','required maxlength="300"')}${select('Kind','kind',[['bill','Bill / card payment'],['income','Expected income']])}${field('Amount','amount','number','','min="0.01" step="0.01" required')}${field('Due / arrival date','date','date',now(),'required')}${select('Repeat','repeat',[['once','One time'],['monthly','Every month'],['weekly','Every week']])}${field('Repeat until (optional)','until','date','')}${select('Account','account',accountsOptions('asset'))}${select('Debt account (for repayment)','debtAccount',[['','Not a debt payment'],...accountsOptions('liability')])}${select('Bill already included in budget','budgetCategory',[['','Additional / not classified'],...state.categories.filter(c=>!c.archived&&c.id!=='oneoff'&&!['savings','buffer'].includes(c.type)).map(c=>[c.id,c.name])])}<p>Choose a category only for an ordinary bill already covered by that spending allowance. Income and debt payments remain separate.</p><button class="button">Add to calendar</button></form></section><section class="card wide"><h2>Scheduled does not mean paid</h2><ul class="list">${events.map(o=>`<li><div class="row"><div>${esc(o.name)} · ${esc(cash(Math.abs(o.amount)))}<br><small>${esc(o.date)} · ${o.paid?'Recorded':'Scheduled'}</small></div>${!o.paid&&o.date<=now()?button(o.kind==='income'?'Record received':'Record payment','pay-obligation','quiet',`data-id="${esc(o.id)}"`):`<span class="tag">${o.paid?'Recorded':'Expected · not cash yet'}</span>`}</div></li>`).join('')||'<li>No scheduled events.</li>'}</ul></section></div>`;
}
function outside(){
  return `${header('Keep money outside in perspective.','Loans, gifts and investments have different meanings. Expected returns are not spendable cash.')}
  <section class="card"><h2>Record money sent</h2><form id="outside-given"><div class="formgrid">${field('Person / purpose','name','text','','maxlength="300" required')}${select('Purpose','kind',[['loan','Loan to someone'],['gift','Gift'],['investment','Investment']])}${field('Amount sent','amount','number','','min="0.01" step="0.01" required')}${select('Paid from','account',accountsOptions('asset'))}${field('Date sent','date','date',now(),'required')}${field('Expected return date (optional)','due','date')}${field('Description','note','text','','maxlength="10000"')}</div><button class="button primary">Record money sent</button></form><p>This records the cash leaving once. An expected return is a reminder, not available money.</p></section>
  <section class="card"><div class="tablewrap"><table><thead><tr><th>Person / purpose</th><th>Date</th><th>Amount</th><th>Returned</th><th>Classification</th></tr></thead><tbody>${state.outside.map(o=>`<tr><td>${esc(o.name)}<br><small>${esc(o.note)}</small></td><td>${esc(o.date)}</td><td>${esc(cash(o.amount))}</td><td>${esc(cash(o.returned||0))}</td><td>${o.reversedBy?'<span class="tag">Reversed · history retained</span>':o.transaction?`<span class="tag">${esc(o.kind)} · linked cash entry</span>`:o.kind==='borrowed'?'<span class="tag">Borrowing · see debt account</span>':`<form data-form="classify" data-id="${esc(o.id)}">${select('Meaning','kind',[['unclassified','Needs review'],['gift','Gift'],['loan','Loan to someone'],['investment','Investment']],o.kind)}<button class="button">Save classification</button></form>`}${!o.reversedBy&&['loan','investment'].includes(o.kind)&&o.amount>(o.returned||0)?`<form data-form="outside-return" data-id="${esc(o.id)}">${field('Actual return received','amount','number','','min="0.01" step="0.01" required')}${select('Received into','account',accountsOptions('asset'))}${field('Return date','date','date',now(),'required')}<button class="button">Record partial return</button></form>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No outside records.</td></tr>'}</tbody></table></div></section><div class="notice">Partial returns reduce the outstanding amount only when actual cash is recorded. Borrowed-money repayments belong in Activity’s Debt / card payment flow.</div>`;
}
function notes(){
  return `${header('Give your ideas somewhere to go.','Keep notes beside your goals. Your imported notes and checklists remain intact.')}
  <div class="grid">${state.notes.filter(n=>!n.archived).map(n=>`<section class="card"><h2>${esc(n.title||'Untitled note')}</h2><p class="note-body">${esc(n.body)}</p><ul class="list">${(n.items||[]).map(i=>`<li>${button(`${i.done?'✓':'○'} ${i.text||i.t||i.body||''}`,'toggle-item','quiet',`data-id="${esc(n.id)}" data-index="${(n.items||[]).indexOf(i)}" aria-pressed="${!!i.done}"`)}</li>`).join('')}</ul>${n.goal?`<small>Linked goal: ${esc(state.goals.find(g=>g.id===n.goal)?.name||n.goal)}</small>`:''}<details><summary>Edit note</summary><form data-form="note-edit" data-id="${esc(n.id)}">${field('Title','title','text',n.title,'maxlength="300"')}<label>Note<textarea name="body" maxlength="50000">${esc(n.body)}</textarea></label>${select('Linked goal','goal',[['','No linked goal'],...state.goals.map(g=>[g.id,g.name])],n.goal)}<button class="button">Save note changes</button></form>${button('Archive note','archive-note','quiet',`data-id="${esc(n.id)}"`)}</details></section>`).join('')}<section class="card"><h2>Add a note</h2><ul class="list">${state.notes.filter(n=>n.archived).map(n=>`<li>${esc(n.title||'Untitled note')}${button('Restore note','restore-note','quiet',`data-id="${esc(n.id)}"`)}</li>`).join('')}</ul><form id="note">${field('Title','title','text','','maxlength="300"')}<label>Note<textarea name="body" maxlength="50000"></textarea></label>${select('Link to a goal','goal',[['','No linked goal'],...activeGoals().map(g=>[g.id,g.name])])}<label>Checklist (one item per line)<textarea name="items"></textarea></label><button class="button">Save note</button></form></section></div>`;
}
function reports(){
  const keys=[...new Set([...state.budgets.map(b=>b.key),...state.transactions.map(t=>C.transactionPeriod(state,t))])].sort();
  const sum=C.summary(state);
  return `${header('A record you can understand.','Spending, plans, debt and reconciliation—with their assumptions visible.')}
  <div class="actions no-print">${button('Print / Save as PDF','print','primary')}${button('Export transactions CSV','csv-export','quiet')}${button('Complete JSON backup','export','quiet')}</div><div class="stats"><section class="card"><small>Cash</small><div class="number">${esc(cash(sum.cash))}</div></section><section class="card"><small>Debt</small><div class="number">${esc(cash(sum.debt))}</div></section><section class="card"><small>Unresolved checks</small><div class="number">${state.reconciliations.filter(r=>r.status==='unresolved').length}</div></section></div>
  <section class="card"><h2>Budget versus recorded spending</h2><div class="tablewrap"><table><thead><tr><th>Period</th><th>Expected income</th><th>Spending budget</th><th>Recorded spending</th><th>Forecast surplus</th><th>Data quality</th></tr></thead><tbody>${keys.map(k=>{const f=C.periodForecast(state,k);return `<tr><td>${esc(k)}</td><td>${esc(cash(f.income))}</td><td>${esc(cash(f.spending))}</td><td>${esc(cash(C.expenseTotal(state,k)))}</td><td class="${f.capacity<0?'negative':''}">${esc(cash(f.capacity))}</td><td>Incomplete tracking<br><small>Unlogged budgets are not actual expenses.</small></td></tr>`;}).join('')}</tbody></table></div></section>
  ${state.legacy?`<section class="card"><h2>Original monthly results, preserved</h2><p>These are the original app’s calculations at import. Estimated months remain estimates. Negative periods stay negative.</p><div class="tablewrap"><table><thead><tr><th>Period</th><th>Original projection</th><th>Original recorded override</th><th>Status</th></tr></thead><tbody>${state.legacy.estimates.map(e=>`<tr><td>${esc(e.key)}</td><td class="${e.predicted<0?'negative':''}">${esc(cash(e.predicted))}</td><td>${e.recorded===null?'None':esc(cash(e.recorded))}</td><td>${esc(e.status)}</td></tr>`).join('')}</tbody></table></div></section>`:''}<p class="print-only">Printed ${esc(now())}. This report includes budget assumptions and incomplete historical tracking; it is not a bank statement.</p>`;
}
function backup(){
  return `${header('Your history stays yours.','Preview imports before applying them. Every saved change has a recovery checkpoint.')}
  <div class="grid"><section class="card"><h2>Import a PLAN backup</h2><p>Your original file is retained losslessly. Importing the same original again will not duplicate or overwrite your newer records.</p><label class="file">Choose a PLAN JSON backup<input id="backup-file" type="file" accept=".json,application/json"></label>
  ${preview?`<div class="notice"><strong>Ready to review</strong><p>${preview.accounts.length} accounts · ${preview.transactions.length} transactions · ${preview.budgets.length} periods · ${preview.goals.length} goals · ${preview.outside.length} outside records · ${preview.notes.length} notes.</p><p>${state.accounts.length?'Applying replaces this workspace after keeping a recovery snapshot.':'This creates your new workspace.'}</p>${button('Apply reviewed backup','apply-backup','primary')}${button('Cancel preview','cancel-preview','quiet')}</div>`:''}
  <div class="actions">${button('Download complete backup','export','primary')}${state.legacy?button('Download original backup','export-original','quiet'):''}</div></section><section class="card"><h2>Recovery checkpoints</h2><p>Recent saves stay on this device. Downloads are independent copies you can store somewhere safe.</p><div class="actions">${button('List recovery checkpoints','list-snapshots','quiet')}${button('Download held sync history','export-sync-recovery','quiet')}</div><ul class="list">${restores.slice(0,8).map(r=>`<li><div class="row"><div>${esc(r.at)}<br><small>${r.state.transactions.length} transactions · revision ${r.revision}</small></div>${button('Preview','preview-snapshot','quiet',`data-id="${esc(r.id)}"`)}</div></li>`).join('')}</ul></section>
  <section class="card wide"><h2>CSV transaction import</h2>${state.imports.some(i=>i.type==='csv'&&!i.undone)?`<p>A saved CSV batch can be undone even after restarting PLAN.</p>${button('Undo latest saved CSV batch','undo-csv','quiet')}`:''}<label class="file">Choose CSV<input id="csv-file" type="file" accept=".csv,text/csv"></label>${csv?`<form id="csv-map"><div class="formgrid">${select('Date column (YYYY-MM-DD)','date',csv.parsed.headers.map(h=>[h,h]),csvMapping?.date||csv.parsed.headers[0])}${select('Amount column','amount',csv.parsed.headers.map(h=>[h,h]),csvMapping?.amount||csv.parsed.headers.find(h=>/amount/i.test(h))||'')}${select('Description column','note',[['','None'],...csv.parsed.headers.map(h=>[h,h])],csvMapping?.note??(csv.parsed.headers.find(h=>/note|description/i.test(h))||''))}${select('Import into account','account',accountsOptions(),csvMapping?.account||'')}${select('Amount sign','sign',[['negative-expense','Negative is spending'],['positive-expense','Positive is spending']],csvMapping?.sign||'negative-expense')}${select('Positive receipts (negative-spending format)','creditKind',[['income','Income'],['refund','Refund of previous spending']],csvMapping?.creditKind||'income')}${select('Type column (optional canonical kinds)','kindColumn',[['','Use sign mapping'],...csv.parsed.headers.map(h=>[h,h])],csvMapping?.kindColumn||'')}${select('Destination for typed transfer / debt payment','toAccount',[['','No destination'],...accountsOptions()],csvMapping?.toAccount||'')}${select('Category','category',state.categories.filter(c=>!c.archived&&!['savings','buffer'].includes(c.type)).map(c=>[c.id,c.name]),csvMapping?.category||'oneoff')}</div><button class="button">Preview rows</button></form>`:''}${csvRows?`<p>Review transfers and card payments explicitly: ordinary sign mapping cannot identify them. A type column can contain expense, income, refund, transfer, repayment, borrow, loan-out or loan-return.</p><p>${csvRows.filter(r=>!r.duplicate&&!r.error).length} new · ${csvRows.filter(r=>r.duplicate).length} duplicates · ${csvRows.filter(r=>r.error).length} invalid.</p><div class="tablewrap"><table><thead><tr><th>Date</th><th>Description</th><th>Amount / type</th><th>Status</th></tr></thead><tbody>${csvRows.slice(0,100).map(r=>`<tr><td>${esc(r.record?.date||'')}</td><td>${esc(r.record?.note||'')}</td><td>${r.record?esc(cash(r.record.amount))+' · '+esc(r.record.kind):''}</td><td>${esc(r.error||(r.duplicate?'Duplicate · skipped':'Ready'))}</td></tr>`).join('')}</tbody></table></div><div class="actions">${button('Import reviewed rows','apply-csv','primary')}${button('Undo last CSV import','undo-csv','quiet')}</div>`:''}</section></div>`;
}
function more(){return `${header('Keep the whole picture close.','Tools for maintaining your finances and protecting your records.')}<div class="grid">${[['accounts','Accounts & weekly check','Reconcile bank, wallet and debt balances.'],['budget','Period budgets','See what is realistic before allocating income.'],['calendar','Cash-flow calendar','Track due dates and actual payments.'],['outside','Money outside','Classify gifts, loans and investments.'],['notes','Notes & checklists','Keep your ideas beside your goals.'],['reports','Reports & exports','Readable multilingual print and transaction CSV.'],['backup','Backup & recovery','Import, export and review restore checkpoints.'],['settings','Preferences','Protected savings and dated cycle changes.'],['ai','Planning assistant','Calculate the income gap for a goal deadline.'],['debts','Debt payoff comparisons','Compare repayment order and explicit interest estimates.']].map(([id,name,desc])=>`<section class="card"><h2>${name}</h2><p>${desc}</p><div class="actions">${button('Open','navigate','quiet',`data-to="${id}"`)}</div></section>`).join('')}</div>`;}
function settings(){const last=state.cycleHistory.filter(c=>c.status!=='cancelled').sort((a,b)=>a.effective.localeCompare(b.effective)).at(-1),anchor=last?.effective>now()?last.effective:now(),nextBoundary=C.workspacePeriodDates(state,C.workspacePeriod(state,anchor)).next;return `${header('Make PLAN fit your life.','Preferences affect future planning; historical records remain intact.')}<section class="card"><form id="settings"><div class="formgrid">${field('Your name','name','text',state.name,'maxlength="300"')}${field('Protected cash reserve','reserve','number',state.settings.reserve/100,'min="0" step="0.01"')}${field('New protected saving each period','monthlyProtection','number',state.settings.monthlyProtection/100,'min="0" step="0.01"')}${field('Timezone','timezone','text',state.timezone,'required')}</div><p>Currency: ${esc(state.currency)}. Changing currency requires explicit conversion rather than relabeling your balances.</p><button class="button primary">Save preferences</button></form><hr class="divider"><h2>Future cycle change</h2><form id="cycle">${field('New cycle start day','start','number',state.cycleStart,'min="1" max="31" required')}${field('Effective from','effective','date',nextBoundary,'required')}<button class="button">Schedule cycle change</button></form><p>Changes activate by date. The first period bridges from the old boundary to the new day in the following month; review its budget because its length differs.<ul class="list">${state.cycleHistory.map(c=>`<li>${esc(c.effective)} · start day ${c.start} · ${c.status==='cancelled'?'Cancelled':c.effective<=now()?'In effect':'Scheduled'}${c.status!=='cancelled'&&c.effective>now()?button('Cancel future change','cancel-cycle','quiet',`data-id="${esc(c.id)}"`):''}</li>`).join('')}</ul></p></section>`;}
function debts(){const liabilities=state.accounts.filter(a=>a.kind==='liability');return `${header('Find a debt payoff path.','Compare estimates before choosing a repayment plan. No payments are recorded here.')}<section class="card"><h2>One debt</h2><form id="payoff"><div class="formgrid">${field('Balance owed','balance','number','','min="0" step="0.01" required')}${field('Annual interest rate %','annualRate','number','','min="0" max="100" step="0.0001" required')}${field('Monthly payment','payment','number','','min="0.01" step="0.01" required')}</div><button class="button primary">Estimate payoff</button></form>${singlePayoff?`<div class="notice">${singlePayoff.feasible?`${singlePayoff.months} months · total ${esc(cash(singlePayoff.total))} · estimated interest ${esc(cash(singlePayoff.interest))}`:esc(singlePayoff.reason)}</div>`:''}</section><section class="card"><h2>Compare all debt accounts</h2>${liabilities.length?`<form id="debt-plan">${liabilities.map(a=>{const balance=C.accountBalance(state,a.id);return `<fieldset><legend>${esc(a.name)}</legend><p>${a.verified?'From your last balance check':'Check the statement; imported or unverified balances are estimates.'}</p><div class="formgrid">${field('Balance owed · '+a.name,'balance:'+a.id,'number',debtInput?.['balance:'+a.id]??(balance===null?'':Math.max(0,-balance)/100),'min="0" step="0.01" required')}${field('APR % · '+a.name,'apr:'+a.id,'number',debtInput?.['apr:'+a.id]??'','min="0" max="100" step="0.0001" required')}${field('Minimum each month · '+a.name,'minimum:'+a.id,'number',debtInput?.['minimum:'+a.id]??'','min="0" step="0.01" required')}</div></fieldset>`;}).join('')}${field('Extra payment above all minimums','extra','number',debtInput?.extra??0,'min="0" step="0.01" required')}<button class="button primary">Compare repayment orders</button></form>`:`<p>Add your debt accounts and confirm their balances to compare them together.</p>${button('Review accounts','navigate','quiet','data-to="accounts"')}`}${debtComparison?`<div class="grid">${debtComparison.map(r=>`<div class="card"><h3>${r.strategy==='avalanche'?'Highest interest first':'Smallest balance first'}</h3><p>Monthly budget: ${esc(cash(r.monthlyBudget))}. Freed minimum payments continue toward the next debt.</p>${r.feasible?`<div class="number">${r.months} months</div><p>Total paid ${esc(cash(r.total))} · interest ${esc(cash(r.interest))}</p><p>First cleared: ${esc(r.payoffs[0]?.name||'Already settled')}${r.payoffs.length?` in month ${r.payoffs[0].month}`:''}.</p>`:`<p class="negative">${esc(r.reason)}</p>`}${r.negativeAmortization?'<p class="negative">At least one debt grows during part of this estimate because its payment is below its interest.</p>':''}</div>`).join('')}</div>`:''}</section><div class="notice">Estimates use monthly APR interest rounded to the currency’s smallest unit. Rates, minimums and the total monthly budget stay fixed. Fees, new borrowing, changing rates and daily card interest are excluded. Use the statement’s terms for an actual repayment decision. Enter 0 explicitly for an interest-free debt.</div>`;}
function assistant(){const purchases=activeGoals().filter(g=>!g.protected),date=C.workspacePeriodDates(state,C.addMonths(period(),2)).to;return `${header('Turn a target into a practical path.','Calculate what would need to change before choosing a date.')}<section class="card"><h2>What would fund this goal by then?</h2>${purchases.length?`<form id="goal-path"><div class="formgrid">${select('Goal to fund','goal',purchases.map(g=>[g.id,g.name]),goalPathInput?.goal||purchases[0].id)}${field('Target funding date','deadline','date',goalPathInput?.deadline||date,'required min="'+esc(now())+'"')}</div><button class="button primary">Calculate a path</button></form>`:button('Add a purchase goal','navigate','primary','data-to="goals"')}${goalPathPreview?`<div class="notice"><strong>${goalPathPreview.feasible?(goalPathPreview.additionalIncome?`Additional income needed: ${esc(cash(goalPathPreview.additionalIncome))} each future period`:'This goal fits without additional income under these assumptions'):esc(goalPathPreview.reason)}</strong>${goalPathPreview.feasible?`<p>Forecast funding: ${esc(goalPathPreview.ready)}. This scenario gives your selected goal a hard deadline.</p>`:''}<ul class="list">${(goalPathPreview.plan?.warnings||[]).map(w=>`<li>${esc(w.replace(/(\d+) minor units/g,(_,n)=>cash(Number(n))))}</li>`).join('')}${goalPathPreview.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div>`:''}</section><section class="card"><h2>Your calculations work locally</h2><p>AI explanations are not connected yet. You can already compare a shared funding schedule, calculate the income gap and check bill timing without an AI subscription.</p><div class="actions">${button('Compare all goals','navigate','quiet','data-to="plan"')}${button('Check purchase timing','navigate','quiet','data-to="calendar"')}</div></section>`;}
async function commit(next,message='Saved on this device',options={}) {
  if(!db)throw new Error('Storage is unavailable. Download a backup before proceeding.');
  busy=true;saved='Saving…';render();
  try{const newRevision=await saveStore(db,next,revision,pendingForm?.draftId||null,options);if(pendingForm?.draftId){drafts=drafts.filter(d=>d.id!==pendingForm.draftId);activeDraftId=null;}state=next;revision=newRevision;purchasePreview=null;goalPathPreview=null;debtComparison=null;singlePayoff=null;failedDraft=null;error='';saved='Saved on this device';notify(message);}
  catch(e){error=e.message;saved='Save failed · changes not applied';failedDraft={id:C.uid(),at:new Date().toISOString(),tab,baseRevision:revision,form:pendingForm,proposedState:C.clone(next),reason:e.message};drafts.push(failedDraft);try{await saveDraft(db,failedDraft);}catch{error+=' Draft storage also failed; download the draft now.';}throw e;}
  finally{busy=false;render();}
}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function exportBackup(){const payload=C.clone(state),hash=await C.digest(JSON.stringify(payload));download(`plan-backup-v2-${now()}.json`,JSON.stringify({app:'plan',schema:2,exported:new Date().toISOString(),digest:hash,data:payload},null,2));}
async function prepareBackup(raw){
  let parsed;try{parsed=JSON.parse(raw);}catch{throw new Error('This is not valid JSON.');}
  if(parsed.app==='plan'&&parsed.schema===2) {
    if(!parsed.digest||await C.digest(JSON.stringify(parsed.data))!==parsed.digest)throw new Error('Backup integrity check failed. It has not been imported.');
    preview=C.validateState(parsed.data);
  }else {
    const hash=await C.digest(raw);
    if(state.imports.some(i=>i.id===hash))throw new Error('This original backup is already imported. Your newer records have been kept.');
    preview=await C.migrateLegacy(raw,now());
  }
  render();
}
function bind(){
  root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});
  root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(()=>action(b.dataset.action,b.dataset)));
  root.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f));failedDraft=null;const selected=drafts.find(d=>d.id===activeDraftId),formId=f.id||f.dataset.form,record=f.dataset.id||'';pendingForm={id:formId,record,values:data,draftId:selected?.form?.id===formId&&(selected.form.record||'')===record?activeDraftId:null};run(()=>submit(pendingForm.id,data,f.dataset));});
  const mapForm=root.querySelector('#csv-map');if(mapForm)mapForm.onchange=()=>{csvMapping=Object.fromEntries(new FormData(mapForm));csvRows=null;render();};
  const file=root.querySelector('#backup-file');if(file)file.onchange=()=>run(async()=>{if(file.files[0])await prepareBackup(await file.files[0].text());});
  const cfile=root.querySelector('#csv-file');if(cfile)cfile.onchange=()=>run(async()=>{if(cfile.files[0]){const raw=await cfile.files[0].text();csv={raw,parsed:C.csvParse(raw)};csvRows=null;csvMapping=null;render();}});
}
async function run(fn){if(busy)return;try{await fn();failedDraft=null;pendingForm=null;}catch(e){error=e.message;if(!failedDraft&&pendingForm){failedDraft={id:C.uid(),at:new Date().toISOString(),tab,baseRevision:revision,form:pendingForm,reason:e.message};drafts.push(failedDraft);if(db)try{await saveDraft(db,failedDraft);}catch{error+=' Draft storage failed; download it now.';}}render();}finally{pendingForm=null;}}
let lastCsvIds=[],csvMapping=null;
async function action(name,data){
  if(name==='correct-entry'){correctionId=data.id;render();}
  if(name==='cancel-correction'){correctionId=null;render();}
  if(name==='toggle-item')await commit(C.mutate(state,'note-item-toggle',{id:data.id,index:Number(data.index)},n=>{const item=n.notes.find(n=>n.id===data.id)?.items?.[Number(data.index)];if(!item)throw new Error('Checklist item not found.');item.done=!item.done;}));
  if(name==='restore-note')await commit(C.mutate(state,'note-restore',{id:data.id},n=>{n.notes.find(n=>n.id===data.id).archived=false;}));
  if(name==='archive-note')await commit(C.mutate(state,'note-archive',{id:data.id},n=>{n.notes.find(n=>n.id===data.id).archived=true;}));
  if(name==='category-archive')await commit(C.mutate(state,'category-archive',{id:data.id},n=>{const c=n.categories.find(c=>c.id===data.id);if(!c||['oneoff','savings','buffer'].includes(c.id))throw new Error('Keep built-in categories available.');c.archived=!c.archived;}));
  if(name==='review-draft'){const d=drafts.find(d=>d.id===data.id);if(!d?.form)throw new Error('Download this draft for review.');const latest=await loadStore(db);if(latest.state){state=latest.state;revision=latest.revision;}failedDraft=d;activeDraftId=d.id;if(d.form.id==='correction')correctionId=d.form.record;tab=d.tab;error='Review this draft against your latest saved records before submitting. Nothing has been applied.';render();}
  if(name==='export-draft'){const draft=drafts.find(d=>d.id===data.id);if(draft)download(`plan-unsaved-draft-${draft.id}.json`,JSON.stringify({app:'plan-draft',reviewOnly:true,draft},null,2));}
  if(name==='discard-draft'){if(db)await removeDraft(db,data.id);drafts=drafts.filter(d=>d.id!==data.id);if(failedDraft?.id===data.id)failedDraft=null;render();}
  if(name==='navigate'){tab=data.to;render();}
  if(name==='dismiss'){error='';render();}
  if(name==='start'){const next=C.fresh();next.categories=[{id:'oneoff',name:'Uncategorized',type:'variable'},{id:'savings',name:'Savings',type:'savings'},{id:'buffer',name:'Buffer',type:'buffer'}];next.accounts=[{id:'bank',name:'Bank / savings',kind:'asset',currency:next.currency,opening:null,baselineDate:now(),baselineSeq:0}];await commit(next);}
  if(name==='apply-backup'&&preview){await commit(preview,'Backup applied. All original records retained.',{restore:true});preview=null;tab='home';render();}
  if(name==='cancel-preview'){preview=null;render();}
  if(name==='export')await exportBackup();
  if(name==='export-original'&&state.legacy)download('plan-original-preserved.json',state.legacy.rawText||JSON.stringify(state.legacy.raw,null,2));
  if(name==='csv-export')download(`plan-transactions-${now()}.csv`,C.csvExport(state),'text/csv;charset=utf-8');
  if(name==='print')window.print();
  if(name==='export-sync-recovery'){const recovery=await syncRecovery(db);download('plan-held-sync-history-'+now()+'.json',JSON.stringify(recovery,null,2));notify('Local sync history downloaded for review; it must not be automatically replayed.');}
  if(name==='list-snapshots'){restores=await snapshots(db);render();}
  if(name==='preview-snapshot'){preview=C.clone(restores.find(r=>r.id===data.id).state);render();}
  if(name==='activity-page'){activityPage=Math.max(0,Number(data.page)||0);render();return;}
  if(name==='clear-filters'){query='';filter='all';activityFilters={account:'',category:'',from:'',to:'',status:'all'};activityPage=0;render();return;}
  if(name==='cancel-cycle')await commit(C.cancelCycle(state,data.id));
  if(name==='reverse')await commit(C.reverseTransaction(state,data.id));
  if(name==='archive-goal')await commit(C.archiveGoal(state,data.id));
  if(name==='save-protection')await commit(C.mutate(state,'settings',{monthlyProtection:scenario.protection??state.settings.monthlyProtection},n=>{n.settings.monthlyProtection=scenario.protection??n.settings.monthlyProtection;}));
  if(name==='apply-csv'&&csvRows){const before=new Set(state.transactions.map(t=>t.id)),next=C.applyCsv(state,csvRows),added=next.transactions.filter(t=>!before.has(t.id)).map(t=>t.id);if(added.length){await commit(next,`${added.length} transactions imported`);lastCsvIds=added;}else notify('No new rows; existing records were kept.');csvRows=await C.csvPreview(state,csv.raw,csvMapping||{});render();}
  if(name==='undo-csv'){const batch=state.imports.filter(i=>i.type==='csv'&&!i.undone).at(-1);if(!batch)throw new Error('No active CSV import to undo.');await commit(C.undoCsv(state,batch.id),'CSV import reversed; history retained');lastCsvIds=[];if(csv&&csvMapping)csvRows=await C.csvPreview(state,csv.raw,csvMapping);render();}
  if(name==='pay-obligation'){
    await commit(C.recordScheduled(state,data.id,now()),'Actual payment recorded; future occurrences remain scheduled');
  }
}
async function submit(id,d,data){
  if(id==='note-edit')return commit(C.mutate(state,'note-edit',{id:data.id,...d},n=>Object.assign(n.notes.find(n=>n.id===data.id),{title:d.title,body:d.body,goal:d.goal,updated:Date.now()}))); 
  if(id==='transaction'){const splits=d.splitAmount1||d.splitAmount2?[{category:d.splitCategory1,amount:C.money(d.splitAmount1)},{category:d.splitCategory2,amount:C.money(d.splitAmount2)}]:undefined;return commit(C.addTransaction(state,{...d,amount:C.money(d.amount),...(splits?{splits}:{})}),'Transaction recorded');}
  if(id==='goal-path'){goalPathInput=d;goalPathPreview=C.goalIncomePath(state,{id:d.goal,deadline:d.deadline});render();return;}
  if(id==='purchase-preview'){purchasePreviewInput=d;const options={amount:C.money(d.amount),account:d.account,budgetAccount:d.budgetAccount,days:Number(d.days),goalId:d.goalId||''};if(d.mode==='earliest'){const window=C.purchaseWindow(state,options);purchasePreview={...window.preview,earliest:window.earliest,dateSearch:true,assumptions:window.assumptions};}else purchasePreview=C.purchaseSafety(state,{...options,date:d.date});render();return;}
  if(id==='search'){if(d.from)C.dateKey(d.from);if(d.to)C.dateKey(d.to);if(d.from&&d.to&&d.from>d.to)throw new Error('The filter end date must follow its start.');query=d.query;filter=d.filter;activityFilters={account:d.account,category:d.category,from:d.from,to:d.to,status:d.status};activityPage=0;render();return;}
  if(id==='scenario'){scenario={mode:d.mode,extraExpense:C.money(d.extraExpense),incomeChange:C.money(d.incomeChange),protection:C.money(d.protection)};render();return;}
  if(id==='reconcile')return commit(C.reconcile(state,{account:data.id,date:d.date,balance:C.money(d.balance),note:d.note}),'Balance check recorded');
  if(id==='account')return commit(C.mutate(state,'account-add',d,n=>n.accounts.push({id:C.uid(),name:d.name,kind:d.kind,currency:n.currency,opening:null,baselineDate:now(),baselineSeq:n.seq}))); 
  if(id==='goal'){
    const input={id:C.uid(),name:d.name,target:C.money(d.target),priority:Number(d.priority),desired:d.desired,protected:!!d.protected,flexible:d.flexibility!=='hard',archived:false,kind:d.kind,recurringCost:C.money(d.recurringCost||0),quantity:d.quantity?Number(d.quantity):null,unitPrice:d.unitPrice?C.money(d.unitPrice):null,fees:C.money(d.fees||0),quoteDate:d.quoteDate||'',icon:d.kind==='gold'?'◇':'◉'};
    if(input.target<=0)throw new Error('Goal target must be above zero.');
    await commit(C.mutate(state,'goal-add',input,n=>{n.goals.push(input);n.reservations[input.id]=0;}));return;
  }
  if(id==='goal-edit')return commit(C.mutate(state,'goal-edit',{id:data.id,...d},n=>{Object.assign(n.goals.find(g=>g.id===data.id),{target:C.money(d.target),priority:Number(d.priority),desired:d.desired,flexible:d.flexibility!=='hard'});}));
  if(id==='reserve')return commit((d.action==='reserve'?C.reserveGoal:C.releaseGoal)(state,data.id,C.money(d.amount)));
  if(id==='purchase'){
    await commit(C.purchaseGoal(state,{id:data.id,amount:C.money(d.amount),account:d.account,date:d.date,complete:d.completion!=='partial',quantity:d.quantity?Number(d.quantity):null}),'Purchase recorded; remaining funding updated');return;
  }
  if(id==='budget-period'){budgetKey=d.key;render();return;}
  if(id==='budget'){
    if(data.key<period())throw new Error('Historical budgets are retained. Record an explicit transaction correction instead.');
    const alloc=Object.fromEntries(Object.entries(d).filter(([k])=>k.startsWith('alloc:')).map(([k,v])=>[k.slice(6),C.money(v)])),salary=C.money(d.salary);
    return commit(C.mutate(state,'budget-set',{key:data.key,salary,alloc},n=>{const old=n.budgets.find(b=>b.key===data.key),budget={id:data.key,key:data.key,salary,alloc,locks:C.clone(old?.locks||{}),revision:(old?.revision||0)+1,status:'planned',source:'manual'};if(old)n.budgets[n.budgets.indexOf(old)]=budget;else n.budgets.push(budget);}));
  }
  if(id==='category')return commit(C.mutate(state,'category-add',d,n=>n.categories.push({id:C.uid(),name:d.name,type:d.type,archived:false})));
  if(id==='obligation'){
    const amount=C.money(d.amount);C.validMoney(amount);C.dateKey(d.date);
    return commit(C.mutate(state,'obligation-add',d,n=>n.obligations.push({id:C.uid(),name:d.name,kind:d.kind,amount:d.kind==='income'?-amount:amount,date:d.date,account:d.account,debtAccount:d.debtAccount,budgetCategory:d.budgetCategory||'',paid:false,...(d.repeat!=='once'?{recurrence:{unit:d.repeat,interval:1,until:d.until||''}}:{})})));
  }
  if(id==='balance-review')return commit(C.reviewReconciliation(state,{id:data.id,note:d.note}),'Explanation saved; original balance difference retained');
  if(id==='outside-given')return commit(C.giveOutside(state,{name:d.name,kind:d.kind,amount:C.money(d.amount),account:d.account,date:d.date,note:d.note,due:d.due}),'Outgoing money and its record saved together');
  if(id==='outside-return')return commit(C.returnOutside(state,{id:data.id,amount:C.money(d.amount),account:d.account,date:d.date}),'Partial return linked and cash recorded');
  if(id==='correction'){await commit(C.correctTransaction(state,{id:data.id,reason:d.reason,replacement:{kind:d.kind,date:d.date,amount:C.money(d.amount),account:d.account,category:d.category,note:d.note}}),'Correction saved; original and replacement retained.');correctionId=null;render();return;}
  if(id==='payoff'){if(!d.annualRate.trim())throw new Error('Enter an explicit interest rate, including 0 for an interest-free debt.');singlePayoff=C.debtPayoff({balance:C.money(d.balance),payment:C.money(d.payment),annualRate:Number(d.annualRate)});render();return;}
  if(id==='debt-plan'){const debts=state.accounts.filter(a=>a.kind==='liability').map(a=>{if(!d['apr:'+a.id].trim())throw new Error('Enter an explicit APR for every debt.');return {id:a.id,name:a.name,balance:C.money(d['balance:'+a.id]),annualRate:d['apr:'+a.id],minimum:C.money(d['minimum:'+a.id])};});debtInput=d;debtComparison=C.debtStrategies({debts,extra:C.money(d.extra)});render();return;}
  if(id==='classify')return commit(C.mutate(state,'outside-classify',{id:data.id,kind:d.kind},n=>{n.outside.find(o=>o.id===data.id).kind=d.kind;}));
  if(id==='note')return commit(C.mutate(state,'note-add',d,n=>n.notes.push({id:C.uid(),title:d.title,body:d.body,items:d.items.split('\n').filter(t=>t.trim()).map(text=>({id:C.uid(),text,done:false})),goal:d.goal,created:Date.now(),updated:Date.now()})));
  if(id==='settings')return commit(C.mutate(state,'settings',d,n=>{n.name=d.name;n.timezone=d.timezone;n.settings.reserve=C.money(d.reserve);n.settings.monthlyProtection=C.money(d.monthlyProtection);}));
  if(id==='cycle')return commit(C.scheduleCycle(state,{start:Number(d.start),effective:d.effective}),'Dated cycle change saved; earlier periods stay intact');
  if(id==='csv-map'){csvMapping=C.clone(d);csvRows=await C.csvPreview(state,csv.raw,d);render();return;}
}
render();
try{
  db=await openStore();const loaded=await loadStore(db);if(loaded.state)state=loaded.state;revision=loaded.revision;saved='Saved on this device';
  drafts=await loadDrafts(db);
  const health=await storageHealth();if(health&&health.usage>health.quota*.9)error='Device storage is nearly full. Download an independent backup.';
  render();
  installOffline(status=>{offlineStatus=status;const label=document.querySelector('#offline-status');if(label)label.textContent=offlineStatus;});
}catch(e){error=e.message;saved='Storage unavailable';render();}
